const items = $input.all();
if (!items.length) return [];
const sd = $getWorkflowStaticData('global');
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h * 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
for (const item of items) {
  const it = item.json;
  const stable = it.guid || it.link || (it.title || '');
  const content_id = 'rss-' + fnv1a(String(stable));
  if (sd.lastContentId === content_id) continue;
  const snippet = (it.contentSnippet || it.content || '').slice(0, 300);
  const topic = [it.title || '', snippet].filter(Boolean).join(' | ');
  return [{ json: { topic, content_id } }];
}
return [];

const msg = $input.first().json;
const content = Array.isArray(msg.content) ? msg.content : [];
const textBlock = content.find(b => b.type === 'text') || content[content.length - 1];
const raw = (textBlock && textBlock.text ? textBlock.text : '').trim();
const clean = raw.replace(/^```json/, '').replace(/```$/, '').trim();
const parsed = JSON.parse(clean);
if (!parsed.hook || !Array.isArray(parsed.blocks) || !parsed.blocks.length) throw new Error('Claude вернул ответ без hook/blocks');
const ALLOWED = ['vpn', 'privacy', 'leaks', 'scam', 'review', 'digest'];
if (typeof parsed.voiceover !== 'string') parsed.voiceover = '';
if (typeof parsed.aftertaste !== 'string') parsed.aftertaste = '';
if (!ALLOWED.includes(parsed.category)) parsed.category = 'digest';
if (typeof parsed.description !== 'string' || !parsed.description.trim()) parsed.description = parsed.hook;
if (!Array.isArray(parsed.hashtags)) parsed.hashtags = [];
parsed.hashtags = parsed.hashtags.filter(t => typeof t === 'string' && t.startsWith('#')).slice(0, 6);
if (!parsed.hashtags.length) parsed.hashtags = ['#интернетбезограничений', '#приватность', '#vpn'];
parsed.topic = $('Format Topic').first().json.topic;
return [{ json: parsed }];

const sd = $getWorkflowStaticData('global');
const cid = $('Format Topic').first().json.content_id;
sd.lastContentId = cid;
// история публикаций по рубрикам — для блока «Ещё по теме» в следующих постах
const s = $('Parse Script').first().json;
const msg = $input.first().json.result || $input.first().json;
const chat = msg.chat || {};
let url = null;
if (msg.message_id) {
  url = chat.username
    ? `https://t.me/${chat.username}/${msg.message_id}`
    : `https://t.me/c/${String(chat.id || '').replace('-100', '')}/${msg.message_id}`;
}
if (url) {
  sd.categoryPosts = sd.categoryPosts || {};
  const list = sd.categoryPosts[s.category] || [];
  list.unshift({ title: s.hook, url });
  sd.categoryPosts[s.category] = list.slice(0, 3);
}
return [{ json: { marked: cid, category: s.category, posted: url } }];

const sd = $getWorkflowStaticData('global');
const s = $('Parse Script').first().json;
const prev = (sd.categoryPosts && sd.categoryPosts[s.category]) || [];
const lines = [s.description, '', s.hashtags.join(' ')];
if (prev.length) {
  lines.push('', '▶ Ещё по теме:');
  for (const p of prev) lines.push(`• ${p.title} — ${p.url}`);
}
lines.push('', '👉 Полный гайд: t.me/INTERNET_BEZ_GRANIC_RUS');
const item = $input.first();
return [{ json: { ...item.json, caption: lines.join('\n') }, binary: item.binary }];
